package com.greenocean.backend;
import com.greenocean.backend.community.service.*;import com.greenocean.backend.common.exception.*;
import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc;import org.springframework.test.context.ActiveProfiles;import org.springframework.transaction.annotation.Transactional;import org.springframework.http.MediaType;import java.util.*;
import static org.assertj.core.api.Assertions.*;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@SpringBootTest @AutoConfigureMockMvc @ActiveProfiles("test") @Transactional
class PhaseM2MembershipTest extends PhaseLFixtures {
 @Autowired GroupMemberships memberships;@Autowired CommunityService communities;
 UUID group(Member owner,String privacy){UUID id=UUID.randomUUID();db.update("INSERT INTO communities(id,name,slug,privacy_type,created_by) VALUES(?,?,?, ?,?)",id,"Synthetic M2 "+id,"g-"+id,privacy,owner.id());db.update("INSERT INTO community_members(community_id,user_id,role,rules_version_ack) VALUES(?,?,'OWNER',1)",id,owner.id());db.update("INSERT INTO community_rules(community_id,position,rule_text) VALUES(?,1,'Respect privacy and platform standards')",id);return id;}
 String groupPost(Member owner,UUID group,String body)throws Exception{var payload=payload(body,true);payload.put("visibility","COMMUNITY");payload.put("communityId",group.toString());return submit("/api/v1/posts",owner,payload,201).path("id").asText();}
 @Test @Tag("happy") void publicJoinRequiresRulesAndDoesNotExposeRosterOrCreateOtherRelationships()throws Exception{
  var owner=member();var reader=member();UUID g=group(owner,"PUBLIC");String post=groupPost(owner,g,"Members-only public-group story");
  mvc.perform(put("/api/v1/communities/"+g+"/membership").header("Authorization","Bearer "+reader.token())).andExpect(status().isBadRequest());
  memberships.join(g,reader.id(),1);memberships.join(g,reader.id(),1);assertThat(read("/api/v1/posts/"+post,reader).path("author").isNull()).isTrue();assertThat(read("/api/v1/communities/"+g+"/details",reader).path("members").size()).isZero();assertThat(db.queryForObject("SELECT count(*) FROM community_members WHERE community_id=? AND user_id=?",Integer.class,g,reader.id())).isEqualTo(1);assertThat(db.queryForObject("SELECT count(*) FROM follows WHERE follower_id=?",Integer.class,reader.id())).isZero();
 }
 @Test @Tag("malicious") void privatePendingCancellationAndOldApprovalsCannotGrantAccess()throws Exception{
  var owner=member();var applicant=member();UUID g=group(owner,"PRIVATE");String post=groupPost(owner,g,"Private group discussion");memberships.join(g,applicant.id(),1);
  mvc.perform(get("/api/v1/posts/"+post).header("Authorization","Bearer "+applicant.token())).andExpect(status().isNotFound());mvc.perform(get("/api/v1/communities/"+g+"/details").header("Authorization","Bearer "+applicant.token())).andExpect(status().isNotFound());
  memberships.cancel(g,applicant.id(),1);assertThatThrownBy(()->memberships.resolve(g,applicant.id(),owner.id(),1,true)).isInstanceOf(ConflictException.class);memberships.join(g,applicant.id(),1);assertThatThrownBy(()->memberships.resolve(g,applicant.id(),owner.id(),1,true)).isInstanceOf(ConflictException.class);memberships.resolve(g,applicant.id(),owner.id(),2,true);read("/api/v1/posts/"+post,applicant);
 }
 @Test @Tag("creative") void hiddenInvitationIsExplicitTargetBoundAndIdempotent()throws Exception{
  var owner=member();var target=member();var outsider=member();UUID g=group(owner,"HIDDEN"),retry=UUID.randomUUID();UUID invite=(UUID)memberships.invite(g,owner.id(),target.id(),retry).get("id");assertThat(memberships.invite(g,owner.id(),target.id(),retry).get("id")).isEqualTo(invite);assertThat(memberships.inbox(target.id()).toString()).contains(invite.toString());assertThat(memberships.inbox(outsider.id())).isEmpty();
  assertThatThrownBy(()->memberships.invitation(invite,outsider.id(),"ACCEPT",1)).isInstanceOf(NotFoundException.class);assertThat(db.queryForObject("SELECT active_group_member(?,?)",Boolean.class,g,target.id())).isFalse();memberships.invitation(invite,target.id(),"ACCEPT",1);memberships.invitation(invite,target.id(),"ACCEPT",1);assertThat(db.queryForObject("SELECT count(*) FROM community_members WHERE community_id=? AND user_id=?",Integer.class,g,target.id())).isEqualTo(1);
 }
 @Test @Tag("malicious") void revokedExpiredOrConsumedInvitesCannotRestoreMembership()throws Exception{
  var owner=member();var target=member();UUID g=group(owner,"HIDDEN");UUID first=(UUID)memberships.invite(g,owner.id(),target.id(),UUID.randomUUID()).get("id");memberships.invitation(first,owner.id(),"REVOKE",0);assertThatThrownBy(()->memberships.invitation(first,target.id(),"ACCEPT",1)).isInstanceOf(NotFoundException.class);
  UUID second=(UUID)memberships.invite(g,owner.id(),target.id(),UUID.randomUUID()).get("id");db.update("UPDATE community_invitations SET expires_at=CURRENT_TIMESTAMP-INTERVAL '1 second' WHERE id=?",second);assertThat(memberships.inbox(target.id())).isEmpty();assertThatThrownBy(()->memberships.invitation(second,target.id(),"ACCEPT",1)).isInstanceOf(NotFoundException.class);
  UUID third=(UUID)memberships.invite(g,owner.id(),target.id(),UUID.randomUUID()).get("id");memberships.invitation(third,target.id(),"ACCEPT",1);memberships.remove(g,target.id(),owner.id(),"REMOVE","Synthetic removal",null);assertThatThrownBy(()->memberships.invitation(third,target.id(),"ACCEPT",1)).isInstanceOf(NotFoundException.class);
 }
 @Test @Tag("malicious") void banRevokesSavedDirectAndAnonymousGroupAccess()throws Exception{
  var owner=member();var target=member();UUID g=group(owner,"PUBLIC");memberships.join(g,target.id(),1);String post=groupPost(owner,g,"Saved group narrative");mvc.perform(put("/api/v1/posts/"+post+"/bookmark").header("Authorization","Bearer "+target.token())).andExpect(status().isNoContent());memberships.remove(g,target.id(),owner.id(),"BAN","Synthetic exclusion",null);
  assertThatThrownBy(()->memberships.join(g,target.id(),1)).isInstanceOf(NotFoundException.class);mvc.perform(get("/api/v1/posts/"+post).header("Authorization","Bearer "+target.token())).andExpect(status().isNotFound());assertThat(read("/api/v1/posts/discovery?mode=SAVED",target).toString()).doesNotContain(post);memberships.unban(g,target.id(),owner.id());memberships.join(g,target.id(),1);read("/api/v1/posts/"+post,target);
 }
 @Test @Tag("confused") void lastOwnerMustTransferAndTargetMustAccept()throws Exception{
  var owner=member();var target=member();var outsider=member();UUID g=group(owner,"PUBLIC");memberships.join(g,target.id(),1);assertThatThrownBy(()->memberships.leave(g,owner.id())).isInstanceOf(ConflictException.class);UUID t=memberships.transfer(g,owner.id(),target.id());assertThat(db.queryForObject("SELECT role FROM community_members WHERE community_id=? AND user_id=?",String.class,g,target.id())).isEqualTo("MEMBER");assertThatThrownBy(()->memberships.acceptTransfer(t,outsider.id(),true)).isInstanceOf(NotFoundException.class);memberships.acceptTransfer(t,target.id(),true);assertThat(db.queryForObject("SELECT role FROM community_members WHERE community_id=? AND user_id=?",String.class,g,target.id())).isEqualTo("OWNER");assertThatThrownBy(()->communities.updateMemberRole(g,target.id(),owner.id(),"MEMBER")).isInstanceOf(ForbiddenException.class);
 }
 @Test @Tag("malicious") void groupModeratorCannotEscalateOrReadPlatformAttribution()throws Exception{
  var owner=member();var moderator=member();UUID g=group(owner,"PUBLIC");memberships.join(g,moderator.id(),1);communities.updateMemberRole(g,moderator.id(),owner.id(),"MODERATOR");assertThatThrownBy(()->communities.updateMemberRole(g,moderator.id(),moderator.id(),"MODERATOR")).isInstanceOf(ForbiddenException.class);assertThatThrownBy(()->memberships.remove(g,owner.id(),moderator.id(),"BAN","Forbidden owner removal",null)).isInstanceOf(ForbiddenException.class);mvc.perform(get("/api/v1/admin/community-proposals").header("Authorization","Bearer "+moderator.token())).andExpect(status().isForbidden());String post=groupPost(owner,g,"Anonymous even to group managers");assertThat(read("/api/v1/posts/"+post,moderator).toString()).doesNotContain(owner.email(),owner.id().toString());
 }
 @Test @Tag("creative") void materialRulesRequireFreshAcknowledgmentWithoutWideningHistoricalContent()throws Exception{
  var owner=member();var reader=member();UUID g=group(owner,"PUBLIC");memberships.join(g,reader.id(),1);communities.replaceRules(g,owner.id(),new com.greenocean.backend.community.dto.UpdateCommunityRulesRequest(List.of("Respect privacy and do not provide treatment")));var in=payload("Pending fresh rule acknowledgment",true);in.put("visibility","COMMUNITY");in.put("communityId",g.toString());submit("/api/v1/posts",reader,in,403);memberships.acknowledge(g,reader.id(),2);submit("/api/v1/posts",reader,in,201);assertThat(db.queryForObject("SELECT count(*) FROM community_rule_revisions WHERE community_id=? AND version=2",Integer.class,g)).isEqualTo(1);
 }
 @Test @Tag("malicious") void blockedInviteTargetAndDemotedInviterCannotGrantHiddenAccess()throws Exception{
  var owner=member();var moderator=member();var target=member();UUID g=group(owner,"HIDDEN");db.update("INSERT INTO community_members(community_id,user_id,role,rules_version_ack) VALUES(?,?,'MODERATOR',1)",g,moderator.id());UUID invitation=(UUID)memberships.invite(g,moderator.id(),target.id(),UUID.randomUUID()).get("id");communities.updateMemberRole(g,moderator.id(),owner.id(),"MEMBER");assertThat(memberships.inbox(target.id())).isEmpty();assertThatThrownBy(()->memberships.invitation(invitation,target.id(),"ACCEPT",1)).isInstanceOf(ForbiddenException.class);db.update("INSERT INTO blocks(blocker_id,blocked_id) VALUES(?,?)",target.id(),owner.id());assertThatThrownBy(()->memberships.invite(g,owner.id(),target.id(),UUID.randomUUID())).isInstanceOf(NotFoundException.class);
 }
}
